from __future__ import annotations


def render_kuzu_risk_page() -> str:
    return """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kuzu 关联风险扩散</title><style>
:root{font-family:"Microsoft YaHei",Arial,sans-serif;color:#e5e7eb;background:#0b1220}*{box-sizing:border-box}body{margin:0}.bar{padding:14px 22px;border-bottom:1px solid #263246;background:#111827;display:flex;gap:14px;align-items:center}.back{color:#93c5fd;text-decoration:none;border:1px solid #2563eb;border-radius:4px;padding:5px 9px}.brand{font-size:18px;font-weight:700}.hint{font-size:12px;color:#aeb7c2}.layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;min-height:calc(100vh - 59px)}.stage{padding:18px}.tools{display:flex;gap:12px;align-items:center;margin-bottom:12px;flex-wrap:wrap}.tools input{width:72px;background:#111827;color:#fff;border:1px solid #475569;border-radius:4px;padding:7px}.tools input[type=checkbox]{width:auto;padding:0;accent-color:#2563eb}.tools button{background:#2563eb;color:#fff;border:0;border-radius:4px;padding:8px 12px;cursor:pointer}.legend{display:flex;gap:10px;font-size:12px;color:#cbd5e1}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:4px}.board{height:calc(100vh - 145px);min-height:560px;border:1px solid #334155;border-radius:8px;background:#101826;overflow:hidden}.board canvas{width:100%;height:100%;display:block}.side{padding:22px;background:#111827;border-left:1px solid #263246}.side h1{font-size:20px;margin:4px 0 16px}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:8px;border-top:1px solid #334155;border-bottom:1px solid #334155;padding:12px 0}.metric b{display:block;font-size:20px}.muted{font-size:12px;color:#94a3b8}.detail{line-height:1.6;font-size:14px;margin-top:18px}.detail ul{padding-left:18px}.error{color:#fca5a5}@media(max-width:900px){.layout{grid-template-columns:1fr}.side{border-left:0;border-top:1px solid #263246}.board{height:560px}}</style></head><body><header class="bar"><a class="back" id="back" href="/">← 返回账户</a><span class="brand">Kuzu 关联风险扩散</span><span class="hint">本机 Kuzu 请求投影 · 超过查询预算会返回部分图谱</span><span class="hint" id="status">读取中…</span></header><main class="layout"><section class="stage"><div class="tools"><label>扩散阈值 <input id="threshold" type="number" min="1" max="100" value="20"></label><label title="全平台同步开平仓核验会明显增加耗时"><input id="includeToxic" type="checkbox"> 包含 Toxic 同步订单（较慢）</label><button id="reload">重新计算</button><span class="legend"><span><i class="dot" style="background:#ef4444"></i>高风险关联</span><span><i class="dot" style="background:#f97316"></i>重点关联</span><span><i class="dot" style="background:#eab308"></i>可扩散</span><span><i class="dot" style="background:#94a3b8"></i>外围线索</span></span></div><div class="board"><canvas id="graph" aria-label="Kuzu 关联风险图"></canvas></div></section><aside class="side"><div class="muted">问题账户</div><h1 id="account">-</h1><div class="metrics"><div class="metric"><span class="muted">节点</span><b id="nodes">-</b></div><div class="metric"><span class="muted">关系</span><b id="edges">-</b></div></div><div class="detail" id="detail">选择节点，查看该账户为何被识别及扩散分。</div></aside></main><script>
const canvas=document.getElementById('graph'),ctx=canvas.getContext('2d'),threshold=document.getElementById('threshold'),status=document.getElementById('status'),detail=document.getElementById('detail');let data=null,positions=new Map();
function fit(){const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);draw()}window.addEventListener('resize',fit);
function layout(){const r=canvas.getBoundingClientRect(),center={x:r.width/2,y:r.height/2},groups=new Map();for(const n of data.entities){const h=Number(n.hops||0);if(!groups.has(h))groups.set(h,[]);groups.get(h).push(n)}positions=new Map();for(const [hop,nodes] of groups){const radius=hop===0?0:Math.min(r.width,r.height)*(0.15+Math.min(hop,8)*.09);nodes.forEach((n,i)=>{const a=hop===0?-Math.PI/2:-Math.PI/2+2*Math.PI*i/nodes.length;positions.set(n.id,{x:center.x+Math.cos(a)*radius,y:center.y+Math.sin(a)*radius})})}}
function draw(){if(!data)return;const r=canvas.getBoundingClientRect();ctx.fillStyle='#101826';ctx.fillRect(0,0,r.width,r.height);for(const e of data.relationships){const a=positions.get(e.source),b=positions.get(e.target);if(!a||!b)continue;ctx.strokeStyle='#64748b';ctx.globalAlpha=.65;ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}ctx.globalAlpha=1;for(const n of data.entities){const p=positions.get(n.id),radius=n.isSubject?27:20;ctx.fillStyle=n.riskColor;ctx.beginPath();ctx.arc(p.x,p.y,radius,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f8fafc';ctx.lineWidth=n.isSubject?3:1;ctx.stroke();ctx.fillStyle='#f8fafc';ctx.font=(n.isSubject?'700 ':'')+'12px Microsoft YaHei';ctx.textAlign='center';ctx.fillText(n.label,p.x,p.y+4);ctx.fillStyle='#cbd5e1';ctx.font='10px Microsoft YaHei';ctx.fillText(n.score.toFixed(1),p.x,p.y+36)}}
function show(n){detail.replaceChildren();const h=document.createElement('h2');h.textContent=n.label;detail.append(h);for(const text of ['调查传播分：'+n.score.toFixed(2),'层级：'+n.riskLevel,'距问题账户：'+(n.hops||0)+' 跳',n.expandable?'该节点继续扩散':'该节点仅保留为线索，未继续扩散']){const p=document.createElement('p');p.textContent=text;detail.append(p)}if(n.scoreLedger.length){const ul=document.createElement('ul');for(const x of n.scoreLedger){const li=document.createElement('li');li.textContent=x.label+'：'+x.contribution.toFixed(2)+'（'+x.evidence.join('；')+'）';ul.append(li)}detail.append(ul)}}
canvas.addEventListener('click',ev=>{if(!data)return;const r=canvas.getBoundingClientRect(),x=ev.clientX-r.left,y=ev.clientY-r.top;for(const n of data.entities){const p=positions.get(n.id);if(Math.hypot(x-p.x,y-p.y)<28){show(n);return}}});
const params=new URLSearchParams(location.search),target=params.get('account')||'',includeToxic=document.getElementById('includeToxic');let requestController=null;if(target){document.getElementById('back').href='/account/'+encodeURIComponent(target)+'?'+params.toString();}function apiUrl(value){if(!target)return '/api/kuzu-risk/graph?threshold='+value;const query=new URLSearchParams();for(const key of ['platform','server','symbol'])if(params.get(key))query.set(key,params.get(key));query.set('threshold',String(value));if(includeToxic.checked)query.set('include_toxic','true');return '/api/accounts/by-login/'+encodeURIComponent(target)+'/relationship-network?'+query.toString();}async function load(){if(requestController)requestController.abort();requestController=new AbortController();const controller=requestController,value=Math.max(1,Math.min(100,Number(threshold.value)||20));threshold.value=value;status.textContent=includeToxic.checked?'读取关系与 Toxic 同步订单中…':'读取关系并评分中…';const timeout=window.setTimeout(()=>controller.abort(),45000);try{const res=await fetch(apiUrl(value),{cache:'no-store',signal:controller.signal});if(!res.ok)throw new Error();data=await res.json();document.getElementById('account').textContent='账户 '+data.account;document.getElementById('nodes').textContent=data.summary.entityCount;document.getElementById('edges').textContent=data.summary.relationshipCount;status.textContent='规则 '+data.summary.ruleVersion+(data.queryBudgetExhausted?' · 查询预算已到，已返回部分图谱':data.truncated?' · 已触发安全上限':' · 完成');layout();fit()}catch(error){if(error.name==='AbortError'){status.textContent='查询超过 45 秒，已停止等待；请提高阈值或取消 Toxic 后重试。';detail.textContent='服务器会在自己的查询预算结束后释放本次只读任务。';}else{status.textContent='图谱读取失败';detail.textContent='请检查账户路由或 Kuzu 本机运行状态。';}}finally{window.clearTimeout(timeout);if(requestController===controller)requestController=null;}}document.getElementById('reload').addEventListener('click',load);load();
</script></body></html>"""
